        [Fact(DisplayName = "motion > a body fits only where every tile it overlaps is open; slide stops at walls but keeps the free axis")]
        public void T002_a_body_fits_only_where_every_tile_it_overlaps_is_open_slide_()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["..#", "..."] });
            expect(Motion.fits(state.grid, Motion.centre(new Point { x = Js.I(1), y = Js.I(0) }), "survivor")).toBe(true);
            expect(Motion.fits(state.grid, new Point { x = Js.I(((2 * Motion.SUB) - Motion.BODY_RADIUS) + 1), y = Js.I(128) }, "survivor")).toBe(false);
            var moved = Motion.slide(state.grid, Motion.centre(new Point { x = Js.I(1), y = Js.I(0) }), 200, 60, "survivor");
            expect(moved.x).toBeLessThanOrEqual((2 * Motion.SUB) - Motion.BODY_RADIUS);
            expect(moved.y).toBe(128 + 60);
        }

        [Fact(DisplayName = "motion > a zombie closes in on you where you stand, between tiles, and stops within reach")]
        public void T003_a_zombie_closes_in_on_you_where_you_stand_between_tiles_and_()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.....", "......"] });
            var you = Js.NN(Js.Get(state.survivors, 0));
            Commands.applyCommand(state, new Command { type = "takeControl", survivorId = you.id });
            you.at = new Point { x = Js.I(128 + 90), y = Js.I(128 + 60) };
            Commands.applyCommand(state, new Command { type = "spawnZombie", x = Js.I(2), y = Js.I(1) });
            var z = Js.NN(Js.Get(state.zombies, 0));
            z.kind = "static";
            for (var t = 0; t < 40; t++)
            {
                Tick.tick(state);
            }
            var d = JsMath.sqrt(Motion.distance2(z.at, you.at));
            expect(d).toBeLessThanOrEqual(Motion.REACH);
            expect(d).toBeGreaterThanOrEqual(Zombies.CROWD - 2);
            expect(you.health).toBeLessThan(1000);
        }

        [Fact(DisplayName = "motion > a crowd pushes apart instead of stacking")]
        public void T004_a_crowd_pushes_apart_instead_of_stacking()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["......", "......", "......"] });
            for (var i = 0; i < 3; i++)
            {
                Commands.applyCommand(state, new Command { type = "spawnZombie", x = Js.I(2), y = Js.I(1) });
            }
            foreach (var z in Js.Iter(state.zombies))
            {
                z.kind = "static";
                z.at = Motion.centre(new Point { x = Js.I(2), y = Js.I(1) });
                z.pos = new Point { x = Js.I(2), y = Js.I(1) };
            }
            for (var t = 0; t < 10; t++)
            {
                Tick.tick(state);
            }
            var (a, b, c) = state.zombies;
            foreach (var (p, q) in new [] { (a, b), (a, c), (b, c) })
            {
                expect(Motion.distance2(p.at, q.at)).toBeGreaterThan(JsMath.pow(((double)(Zombies.CROWD) / (2)), 2));
            }
        }

